/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
  const viewports = api.viewports;

  if (!viewports || !viewports.isRouteInitializationCompleted)
    return 'both';

  // hide the right side panel if there are no active routes.
  return viewports.contextual_sidebar.hasRoutes ? 'both' : 'left';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    if (!api.data.ci_record_uib_config.output || !api.data.ci_record_uib_config.output.slushbucket || !api.data.gform || !api.data.gform.nowRecordFormBlob)
        return [];

    const items = api.data.ci_record_uib_config.output.slushbucket.field_data_source;
    const fieldName = api.data.ci_record_uib_config.output.slushbucket.field_name;
    if (!fieldName)
        return [];

    function _getFormFieldValue(field) {
        try {
            //check if gform is available
            return api.data.gform.nowRecordFormBlob.gForm.getValue(field);
            //Todo: if gform is not available, use event payload??
            // //
            // if (event.name == 'SN_FORM_DATA_CONNECTED#FETCH_SUCCESS') {
            //     const recordValues = event.payload.data.GlideViewQuery_Query.uiView.glideLayoutItem._query.GlideLayout_Query.formLayout.recordValues;
            //     for (var i = 0; i < recordValues.length; i++) {
            //         if (recordValues[i].name == field) return recordValues[i].value;
            //     }
            // }
            return null;
        } catch (e) {
            return null;
        }
    }

    const fieldValues = _getFormFieldValue(fieldName);
    if (!fieldValues)
        return [];

    const selectedItems = fieldValues.split(",").map(function(value) {
        return items.find(function(item) {
            return item.id === value;
        });
    });
    return selectedItems;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    try {
        return !api.data.ci_record_uib_config.output.slushbucket ||
        !api.state.isValidRecord ||
        api.state.hideAllCustomFields ||
        api.state.hideOnLoadCustomFields.slushbucket;
    } catch (e) {
        return true;
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    try {
        return !api.data.ci_record_uib_config.output.script ||
        !api.state.isValidRecord ||
        api.state.hideAllCustomFields ||
        api.state.hideOnLoadCustomFields.script;
    } catch (e) {
        return true;
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({ api }) {
    const breadcrumbsProp = api.data.page_props.output && api.data.page_props.output.breadcrumbs;
    if (breadcrumbsProp)
        return breadcrumbsProp;
    else 
        return [];

}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {any} params.imports
  */
function evaluateProperty({api}) {
	return !api.data.page_props.output;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        table,
        sysId
    } = api.context.props;
    if (table && sysId && table == 'sys_cs_context_profile' && !sysId.startsWith("-1_uid_")) {
        return false;
    }
    return true;
}
